'use strict';
const A=Arena,KEY='roteirizze-torneios-v3',params=new URLSearchParams(location.search),page=typeof SiteRouting!=='undefined'?SiteRouting.pageFromPath(location.pathname):((location.pathname.replace(/\/+$/,'').split('/').pop()||'index').toLowerCase().replace(/\.html$/,'')+'.html');
const isAdmin=['admin.html','inscricoes.html'].includes(page)||(page==='chaveamento.html'&&params.get('admin')==='1');
const isPublicDirectory=!isAdmin&&!params.get('competicao')&&['index.html','chaveamento.html'].includes(page);
let registrationDraft=[];
const cloud=window.TorneioCloud;
let competitionId=params.get('competicao')||'',competitionList=[],organizerList=[],dashboardFilter='all';
const access={ready:false,authorized:false,role:null,session:null,saving:false,blocked:false,error:'',recovery:false};
let booting=null,polling=false,lastServerState=null,formDirty=false;
let comp=A.fresh(),storageError='',selected=params.get('categoria')||'',filter='all',query='',publicView='games',lane='W';
cloud?.configure({admin:isAdmin,id:isAdmin?competitionId:null,token:!isAdmin?competitionId:null});
const $=selector=>document.querySelector(selector),esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function cacheKey(){return KEY+':v5:'+(isAdmin?'admin:'+access.session?.user?.id+':'+competitionId:'public:'+cloud.context.token);}
function url(p,cid,admin=false){const query=new URLSearchParams(),administrative=['admin.html','inscricoes.html'].includes(p)||admin;const identity=administrative?competitionId:cloud?.context.token;if(identity)query.set('competicao',identity);if(cid)query.set('categoria',cid);if(admin&&p==='chaveamento.html')query.set('admin','1');return p+(query.size?'?'+query.toString():'');}
const icons={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',admin:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',bracket:'<path d="M3 4h5v6H3m5-3h5v10H8m5-5h8M3 14h5v6H3"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]}</svg>`;
const categoryMemory=CategoryMemory.create(()=>localStorage);
function categoryContext(){return {scope:isAdmin?'admin:'+(access.session?.user?.id||''):'public',competition:cloud?.context.id||competitionId||cloud?.context.token};}
const getCat=()=>categoryMemory.choose(comp.categories,selected,categoryContext());
function rememberCategory(c){if(!c)return;selected=c.id;categoryMemory.remember(categoryContext(),c.id);const p=new URLSearchParams(location.search);p.set('categoria',c.id);history.replaceState(null,'',location.pathname+'?'+p.toString()+location.hash);}

const gameName=m=>({W:'Chave dos vencedores',L:'Chave dos perdedores',S:'Semifinal',B:'Terceiro lugar',F:'Final'}[m.side]);
const team=(c,id)=>c.teams.find(t=>t.id===id),tname=(c,id)=>esc(A.teamName(team(c,id))),resultLabel={ready:'Pronto',waiting:'Aguardando',live:'Em quadra',done:'Encerrado',conflict:'Em revisão'};
function notify(msg){const el=$('#toast');el.textContent=msg;el.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.style.display='none',4200);}
async function persist(msg,rerender=true){if(!access.authorized||access.saving)return false;comp.updated=new Date().toISOString();access.saving=true;document.body.classList.add('saving');try{const validated=A.validate(comp);await cloud.save(validated);comp=validated;settleLogoSave();lastServerState=JSON.stringify(comp);try{localStorage.setItem(cacheKey(),lastServerState);}catch{}storageError='';access.blocked=false;formDirty=false;if(rerender)render();if(msg)notify(msg);return true;}catch(e){access.blocked=true;storageError=e.message||'Não foi possível salvar. Sua alteração ainda não foi enviada.';render();notify('Alteração não salva. Confira o aviso no painel.');return false;}finally{access.saving=false;document.body.classList.remove('saving');}}
function navigate(p,cid,admin=false){location.href=url(p,cid,admin);}
function counts(c){if(!c)return {total:0,done:0,live:0,ready:0};const all=Object.values(A.resolve(c));return {total:all.length,done:all.filter(m=>m.done).length,live:all.filter(m=>m.status==='live').length,ready:all.filter(m=>m.status==='ready').length};}
function catState(c){if(!c.draw.length)return 'Inscrições';if(!c.confirmed)return 'Sorteio em conferência';return Object.values(A.resolve(c)).find(m=>m.side==='F')?.done?'Finalizada':'Em competição';}
function options(value){return Object.values(A.models).sort((a,b)=>a.n-b.n).map(m=>`<option value="${m.n}" ${m.n===+value?'selected':''}>${m.n} duplas</option>`).join('');}
function categorySelect(c){return `<label class="category-select">Categoria<select id="category-select">${comp.categories.map(x=>`<option value="${esc(x.id)}" ${c&&c.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`;}
function workflow(c,active){return `<nav class="workflow-simple" aria-label="Etapas"><span class="${active===0?'active':''}">Duplas</span><span>›</span><span class="${active===2?'active':''}">Chaveamento</span><span>›</span><span>Acompanhar</span></nav>`;}
function hero(kicker,title,desc,actions=''){return `<section class="hero">${comp.created?logoMark(comp.logoPath,'hero-logo'):''}<div class="copy"><p class="kicker">${kicker}</p><h1>${esc(title)}</h1><p>${desc}</p>${actions?'<div class="actions">'+actions+'</div>':''}</div></section>`;}
function render(){if(bracketController){bracketPosition={category:bracketCategory,view:bracketController.snapshot()};bracketController.destroy();bracketController=null;}if(!access.ready)return renderAccess('loading');if(isAdmin&&(!access.authorized||access.recovery))return renderAccess(access.recovery?'recovery':'login');const c=getCat();if(c)selected=c.id;const view=isPublicDirectory?'Torneios':page==='admin.html'&&!competitionId?'Competições':page==='admin.html'?'Organização':page==='inscricoes.html'?'Inscrições':page==='chaveamento.html'?'Chaveamento':'Acompanhamento';document.body.classList.remove('nav-open');document.title=view+' | '+(comp.created?comp.name:'Roteirizze Torneios');
$('#app').innerHTML=`<div class="app-shell"><button class="nav-backdrop" data-action="close-navigation" tabindex="-1" aria-label="Fechar menu"></button><aside class="sidebar" id="site-sidebar" aria-label="Menu principal"><button class="sidebar-close" data-action="close-navigation">Fechar menu</button><a class="logo" href="${isAdmin?'admin.html':'index.html'}" aria-label="Roteirizze Torneios"><img src="assets/logo-white.png" alt="Roteirizze Estratégias"></a><div class="product"><strong>TORNEIOS</strong><span>Futevôlei · Gestão e live</span></div><nav class="side-nav" aria-label="Menu principal"><a href="${url('index.html',c?.id)}" class="${page==='index.html'?'active':''}">${icon('home')}<span>Acompanhar</span></a><a href="${url('chaveamento.html',c?.id,isAdmin)}" class="${page==='chaveamento.html'?'active':''}">${icon('bracket')}<span>Chaveamento</span></a><a href="admin.html" class="${['admin.html','inscricoes.html'].includes(page)?'active':''}">${icon('admin')}<span>Minhas competições</span></a></nav><div class="sidebar-foot"><b>ROTEIRIZZE TORNEIOS</b><p>Da primeira partida ao título.</p></div></aside><div class="main-wrap"><header class="topbar"><button class="menu-trigger" data-action="open-navigation" aria-controls="site-sidebar" aria-expanded="false" aria-label="Abrir menu">☰ <span>Menu</span></button><span class="crumb">ROTEIRIZZE / ${view.toUpperCase()}</span><div class="toplinks"><span class="sync"><i class="status-dot"></i>${isAdmin?'Conectado':'Acompanhamento'}</span>${isAdmin?'<a class="btn small ghost" href="auth.html?acao=alterar">Alterar senha</a><button class="small ghost" data-action="logout">Sair</button>':''}<a class="btn small ghost" href="${isAdmin?url('index.html',c?.id):'admin.html'}" ${isAdmin?'target="_blank" rel="noopener"':''}>${isAdmin?'Ver acompanhamento ↗':'Painel administrativo'}</a></div></header><main>${storageError?'<div class="local-alert error" role="alert">'+esc(storageError)+(isAdmin&&access.blocked?'<div class="actions" style="margin-top:10px"><button class="small" data-action="retry-save">Tentar salvar</button><button class="small" data-action="export">Exportar tentativa</button><button class="small" data-action="reload-cloud">Recarregar do servidor</button></div>':'')+'</div>':''}<div id="page-content"></div><footer class="footer"><span>Roteirizze Torneios · v5.2.4 · Futevôlei</span><span>${access.blocked?'Alterações não salvas':comp.updated?'Salvo às '+new Date(comp.updated).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'Pronto para começar'}</span></footer></main></div></div>`;
configureNavigation();if(isPublicDirectory)portalPage();else if(page==='admin.html'&&!competitionId)dashboardPage();else if(page==='admin.html')adminPage();else if(page==='inscricoes.html')registrationPage(c);else if(page==='chaveamento.html')bracketPage(c);else publicPage(c);}
function noCategory(){return `<div class="empty"><p class="kicker">Tudo começa na organização</p><h2>Nenhuma categoria cadastrada</h2><p>Crie a competição, escolha as quadras e adicione a primeira categoria para iniciar o sorteio.</p><a class="btn primary" href="admin.html">Abrir organização</a></div>`;}
function stats(items){return `<section class="stats" aria-label="Resumo">${items.map(([label,value,hl])=>`<div class="stat ${hl?'highlight':''}"><span>${label}</span><b>${value}</b></div>`).join('')}</section>`;}
function adminPage(){if(!comp.created){$('#page-content').innerHTML=hero('Comece por aqui','Criar competição','Dê um nome ao evento e escolha quantas quadras estarão disponíveis.')+`<section class="panel"><form data-form="create-competition"><div class="form-grid"><label>Nome da competição<input name="name" maxlength="100" required placeholder="Ex.: Open de Jacobina"></label><label>Quantidade de quadras<select name="courts">${[1,2,3].map(n=>`<option value="${n}">${n} quadra${n>1?'s':''}</option>`).join('')}</select></label></div><div class="actions" style="margin-top:20px"><button type="submit" class="primary">Criar competição</button><button type="button" data-action="import">Importar competição</button><button type="button" data-action="demo">Carregar demonstração</button>${localStorage.getItem(KEY)?'<button type="button" data-action="import-legacy">Importar competição deste navegador</button>':''}</div></form></section>`;return;}const live=A.active(comp),tot=comp.categories.reduce((a,c)=>a+counts(c).done,0);$('#page-content').innerHTML=hero('Painel da organização',comp.name,'Categorias, quadras e resultados em um só lugar.',`<a class="btn" href="admin.html">Minhas competições</a><button class="primary" data-action="new-category">+ Nova categoria</button><button class="ghost" data-action="export">Exportar backup</button><button data-action="copy-public-link" data-token="${esc(cloud.context.token)}">Copiar link público</button>`)+stats([['Categorias',String(comp.categories.length).padStart(2,'0')],['Quadras',String(comp.courts).padStart(2,'0')],['Em quadra',String(live.length).padStart(2,'0'),true],['Jogos encerrados',tot]])+`<section class="panel"><div class="panel-head"><h2>Configuração da competição</h2></div><form data-form="competition"><div class="form-grid"><label>Nome da competição<input name="name" value="${esc(comp.name)}" maxlength="100" required></label><label>Quantidade de quadras<select name="courts">${[1,2,3].map(n=>`<option value="${n}" ${n===comp.courts?'selected':''}>${n} quadra${n>1?'s':''}</option>`).join('')}</select></label></div><div class="actions" style="margin-top:18px"><button type="submit" class="primary">Salvar alterações</button><button type="button" data-action="import">Importar backup</button><button type="button" data-action="demo">Carregar demonstração</button><button type="button" data-action="reset-competition" class="danger">Zerar competição</button></div></form></section>${logoPanel()}<div class="section-head"><h2>Controle das quadras</h2><span class="help">Qualquer partida com as duas duplas definidas pode ser iniciada</span></div>${courts(true)}<div class="section-head"><h2>Categorias da competição</h2><button class="small primary" data-action="new-category">+ Adicionar</button></div><div class="grid">${comp.categories.length?comp.categories.map(c=>categoryCard(c)).join(''):'<div class="empty"><h2>Adicione a primeira categoria</h2><p>Informe a quantidade de duplas e cadastre os atletas.</p><button class="primary" data-action="new-category">Criar categoria</button></div>'}</div>`;}
function categoryCard(c){const n=counts(c);return `<article class="category-card"><span class="tag ${c.confirmed?'live':''}">${catState(c)}</span><h3>${esc(c.name)}</h3><div class="category-meta"><span>${c.count} duplas</span><span>${n.done}/${n.total} jogos</span></div><div class="progress"><i style="width:${n.done/n.total*100}%"></i></div><div class="actions"><a class="btn small primary" href="${url(c.confirmed?'chaveamento.html':'inscricoes.html',c.id,c.confirmed)}">${c.confirmed?'Gerenciar jogos':'Cadastrar duplas'}</a><a class="btn small" href="${url('inscricoes.html',c.id)}">Duplas</a>${c.confirmed?redrawButton(c,true):''}<button class="small danger" data-action="reset-category" data-cid="${esc(c.id)}">Zerar categoria</button><button class="small danger" data-action="delete-category" data-cid="${esc(c.id)}">Excluir categoria</button></div></article>`;}
function courtDrawing(l){return `<div class="sand-court ${l?'in-play':''}" role="img" aria-label="Quadra de futevôlei${l?' com '+tname(l.c,l.m.teams[0])+' contra '+tname(l.c,l.m.teams[1]):' livre'}"><div class="court-lines"><div class="court-half">${l?`<strong>${tname(l.c,l.m.teams[0])}</strong>`:'<span class="court-side">AGUARDANDO</span>'}</div><div class="court-net" aria-hidden="true"></div><div class="court-half">${l?`<strong>${tname(l.c,l.m.teams[1])}</strong>`:'<span class="court-side">PRÓXIMO JOGO</span>'}</div></div></div>`;}
function courts(admin){const live=A.active(comp);return `<div class="court-grid ${comp.courts===1?'one':comp.courts===2?'two':''}">${Array.from({length:comp.courts},(_,i)=>{const n=i+1,l=live.find(x=>x.m.court===n);return `<article class="court ${l?'busy':''}"><div class="court-header"><strong>QUADRA ${n}</strong><span class="tag ${l?'live':''}">${l?'● Em jogo':'Livre'}</span></div><div class="court-body"><p class="kicker">${l?esc(l.c.name)+' · J'+l.m.id:'Futevôlei'}</p>${courtDrawing(l)}<div class="court-controls">${l?(admin?`<button class="small lime" data-action="edit-game" data-cid="${esc(l.c.id)}" data-game="${l.m.id}" data-court="${n}">Lançar resultado</button>`:'<span class="help">Partida em andamento</span>'):(admin?`<button class="primary small" data-action="choose-game" data-court="${n}">Escolher jogo</button>`:'<span class="help">Aguardando próxima partida</span>')}</div></div></article>`;}).join('')}</div>`;}
function registrationPage(c){
 registrationDraft=c?c.teams.map(t=>({...t})):[];
 if(!c){$('#page-content').innerHTML=noCategory();return;}
 const locked=c.confirmed;
 $('#page-content').innerHTML=hero('Inscrições',c.name,locked?'Atualize os nomes das duplas e salve as alterações.':'Cadastre as duplas e salve o preenchimento antes de sortear.')+workflow(c,0)+`<section class="panel"><form data-form="registration" data-cid="${esc(c.id)}" novalidate><div class="form-grid"><label>Nome da categoria<input name="categoryName" maxlength="80" required value="${esc(c.name)}"></label><label>Quantidade de duplas<select id="registration-count" name="count" ${locked?'disabled':''}>${options(c.count)}</select></label></div>${locked?'<div class="notice">Os nomes podem ser alterados a qualquer momento. Posições no sorteio, placares e classificação serão preservados.</div>':`<details class="details"><summary>Colar uma lista de duplas</summary><p>Uma dupla por linha: Atleta 1 / Atleta 2.</p><label style="margin-top:12px">Duplas<textarea id="bulk-teams" rows="5" placeholder="João Silva / Pedro Souza&#10;Lucas Lima / Rafael Santos"></textarea></label><div class="actions" style="margin-top:12px"><button type="button" data-action="apply-bulk">Preencher campos</button><button type="button" data-action="sample-names">Usar nomes de teste</button></div><p class="error-text" id="bulk-error"></p></details>`}<div id="team-inputs" class="team-inputs">${teamInputs(c.teams,locked,c)}</div><p class="error-text" id="registration-error" role="alert"></p><div class="actions"><button class="${locked?'primary':'lime'}" type="submit" name="registrationAction" value="save">${locked?'Salvar alterações':'Salvar sem sortear'}</button>${locked?`<a class="btn lime" href="${url('chaveamento.html',c.id,true)}">Abrir chaveamento</a>`:'<button class="primary" type="submit" name="registrationAction" value="draw">Sortear e abrir chaveamento</button>'}<a class="btn ghost" href="admin.html">Voltar ao painel</a>${locked?redrawButton(c):''}<button type="button" class="danger" data-action="reset-category" data-cid="${esc(c.id)}">Zerar categoria</button><button type="button" class="danger" data-action="delete-category" data-cid="${esc(c.id)}">Excluir categoria</button></div></form></section>`;
}
function isBionic(c,id){return Boolean(c.confirmed&&A.models[c.count].byeSlots.includes(c.draw.indexOf(id)+1));}
function teamInputs(teams,locked,c=getCat()){return teams.map((t,i)=>`<div class="team-form"><div class="team-form-head"><strong>DUPLA ${String(i+1).padStart(2,'0')}</strong><span>${locked&&isBionic(c,t.id)?'Biônico':locked?'Inscrição confirmada':'Inscrição'}</span></div><div class="row"><label>Atleta 1<input name="a${i}" maxlength="60" value="${esc(t.a)}" placeholder="Nome e sobrenome" required></label><label>Atleta 2<input name="b${i}" maxlength="60" value="${esc(t.b)}" placeholder="Nome e sobrenome" required></label></div></div>`).join('');}
const eliminationCache=new WeakMap();
function eliminationGames(c){
 const token=JSON.stringify([c.confirmed,c.draw,c.results,c.routes,c.bracketMode]),cached=eliminationCache.get(c);if(cached?.token===token)return cached.games;
 const resolved=A.resolve(c),matches=A.order(c).map(g=>resolved[g.id]),losses=new Map(),games=new Map();
 // Mark only the result that eliminates a team; earlier appearances keep their original style.
 for(const m of matches)if(m.done&&['W','L'].includes(m.side)){
  const count=(losses.get(m.loser)||0)+1;losses.set(m.loser,count);if(count===2)games.set(m.loser,m.id);
 }
 for(const m of matches)if(m.done&&['F','B'].includes(m.side))games.set(m.loser,m.id);
 // A team with a remaining placement game has not finished competing yet.
 for(const m of matches)if(!m.done)for(const id of m.teams)if(id)games.delete(id);
 const semifinalists=new Set(matches.filter(m=>m.side==='S').flatMap(m=>m.teams).filter(Boolean));for(const id of semifinalists)games.delete(id);
 eliminationCache.set(c,{token,games});return games;
}
function championCrown(){return `<svg class="champion-crown" viewBox="0 0 48 40" fill="none" aria-hidden="true"><path d="M8 29 4 11l12 8L24 5l8 14 12-8-4 18H8Z" fill="currentColor" stroke="#fff1b3" stroke-width="2" stroke-linejoin="round"/><path d="M10 35h28" stroke="currentColor" stroke-width="5" stroke-linecap="round"/><circle cx="24" cy="24" r="2.5" fill="#765016"/><circle cx="4" cy="9" r="3" fill="#fff1b3"/><circle cx="24" cy="4" r="3" fill="#fff1b3"/><circle cx="44" cy="9" r="3" fill="#fff1b3"/></svg>`;}
function card(c,m,admin=false,compact=false){const displayTeams=m.conflict&&admin?m.playedTeams:m.teams,displayScore=m.conflict&&admin?m.savedScore:m.score;const games=eliminationGames(c),eliminated=id=>m.side!=='S'&&m.done&&m.loser===id&&games.get(id)===m.id,champion=id=>m.side==='F'&&m.done&&m.winner===id;return `<article class="match ${m.status} ${m.side==='F'?'final':''}" data-game="${m.id}" data-cid="${esc(c.id)}"><p class="phase">${gameName(m)}</p><div class="top"><b>J${String(m.id).padStart(2,'0')}</b><span class="tag ${m.status}">${m.method==='wo'?'Encerrado por W.O.':resultLabel[m.status]}</span></div>${displayTeams.map((id,i)=>`<div class="team-row ${!id?'pending':''} ${m.done&&m.winner===id?'win':''} ${eliminated(id)?'eliminated':''} ${champion(id)?'champion-team':''}"><span>${id?tname(c,id):sourceLabel(m.refs[i])}${champion(id)?'<small class="champion-label">'+championCrown()+'Campeões</small>':''}${eliminated(id)?'<small class="eliminated-label">Eliminada</small>':''}${m.done&&id&&['F','B'].includes(m.side)&&!(m.side==='F'&&m.winner===id)?'<small class="placement-label">'+(m.side==='F'?'2º lugar':m.winner===id?'3º lugar':'4º lugar')+'</small>':''}${id&&m.refs[i][0]==='T'&&isBionic(c,id)?'<small class="bionic-label">Biônico</small>':''}${id&&!m.conflict&&m.refs[i][0]!=='T'?'<small class="match-source">'+sourceLabel(m.refs[i])+'</small>':''}</span><strong class="${m.method==='wo'?'wo-score':''}">${m.method==='wo'?(m.winner===id?'W.O.':'·'):displayScore?displayScore[i]:'·'}</strong></div>`).join('')}${m.conflict&&admin?'<p class="conflict-card-note">Registro anterior preservado</p>':''}<div class="match-footer"><span>${m.court?'Quadra '+m.court+(m.status==='ready'?' · na fila':''):'Quadra a definir'}</span>${admin?`<button class="small" data-action="edit-game" data-cid="${esc(c.id)}" data-game="${m.id}" ${m.ready||m.conflict?'':'disabled'}>${m.conflict?'Revisar':m.done?'Corrigir':m.status==='live'?'Placar':'Gerenciar'}</button>`:`<span>${m.refs.every(r=>/^[VP]\d+$/.test(r))?m.refs.join(' × '):''}</span>`}</div></article>`;}
function sourceLabel(ref){if(ref==='R')return 'Aguardando cruzamento';if(ref==='Q')return 'Classificado da repescagem';return ref[0]==='T'?'Biônico':(ref[0]==='V'?'Vencedor':'Perdedor')+' do J'+ref.slice(1);}
function podium(c){const all=Object.values(A.resolve(c)),f=all.find(m=>m.side==='F'),b=all.find(m=>m.side==='B');if(!f?.done)return '';return `<section class="champion champion-celebration">${championCrown()}<p class="kicker">Título conquistado · ${esc(c.name)}</p><h2>Campeões: ${tname(c,f.winner)}</h2></section><div class="podium-grid"><div class="podium-place first-place"><b>1º LUGAR</b>${tname(c,f.winner)}</div><div class="podium-place"><b>2º LUGAR</b>${tname(c,f.loser)}</div><div class="podium-place"><b>3º LUGAR</b>${b?.done?tname(c,b.winner):'Aguardando disputa'}</div><div class="podium-place"><b>4º LUGAR</b>${b?.done?tname(c,b.loser):'Aguardando disputa'}</div></div>`;}
function publicPage(c){if(!comp.created){$('#page-content').innerHTML=hero('Acompanhar torneios','Não há competições no momento.','Os eventos aparecerão aqui quando forem criados.')+stats([['Competições',0],['Categorias',0],['Em quadra',0],['Jogos encerrados',0]]);return;}const total=comp.categories.reduce((n,c)=>n+counts(c).done,0);$('#page-content').innerHTML=hero('A competição na palma da mão',comp.name,'Quadras, resultados e o caminho das duplas até a final.','<a class="btn" href="index.html">Todos os torneios</a>')+stats([['Categorias',comp.categories.length],['Quadras',comp.courts],['Em quadra',A.active(comp).length,true],['Jogos encerrados',total]])+`<div class="section-head"><h2>Agora nas quadras</h2><span class="help">Todas as categorias</span></div>${courts(false)}${c?`<div class="toolbar">${categorySelect(c)}<a class="btn primary" href="${url('chaveamento.html',c.id)}">Ver chaveamento</a><button data-action="print">Imprimir tabela completa</button></div><div class="section-head"><h2>${esc(c.name)}</h2><span class="tag">${catState(c)}</span></div><div class="tabs">${[['games','Partidas'],['roster','Duplas'],['standings','Pódio']].map(([v,l])=>`<button data-action="public-view" data-view="${v}" class="${publicView===v?'active':''}">${l}</button>`).join('')}</div><div id="public-body"></div>`:noCategory()}`;if(c)publicBody(c);}
function publicBody(c){if(!c.confirmed){$('#public-body').innerHTML='<div class="empty"><h2>Categoria em preparação</h2><p>Os jogos aparecem após o cadastro das duplas.</p></div>';return;}if(publicView==='roster'){const all=Object.values(A.resolve(c));$('#public-body').innerHTML=`<div class="roster">${c.draw.map((id,i)=>{const losses=all.filter(m=>m.done&&m.loser===id).length;return `<div class="roster-team"><div><strong>${tname(c,id)}</strong><small>${A.models[c.count].byeSlots.includes(i+1)?'Biônico · ':''}${losses} derrota${losses===1?'':'s'}</small></div></div>`;}).join('')}</div>`;return;}if(publicView==='standings'){$('#public-body').innerHTML=podium(c)||'<div class="empty"><h2>O pódio ainda está em disputa</h2><p>A classificação aparecerá após os jogos decisivos.</p></div>';return;}$('#public-body').innerHTML=filters()+`<div class="grid" id="game-list"></div>`;listGames(c,false);}
function filters(){return `<div class="toolbar"><label class="search">Pesquisar dupla ou jogo<input type="search" id="game-search" value="${esc(query)}" placeholder="Nome do atleta ou J12"></label><label>Filtrar jogos<select id="game-filter">${[['all','Todos os jogos'],['live','Em quadra'],['ready','Prontos'],['done','Encerrados'],['waiting','Aguardando'],['conflict','Em revisão'],['W','Chave dos vencedores'],['L','Chave dos perdedores'],['S','Semifinais'],['F','Final'],['B','Terceiro lugar']].map(([v,t])=>`<option value="${v}" ${v===filter?'selected':''}>${t}</option>`).join('')}</select></label></div>`;}
function listGames(c,admin){const all=Object.values(A.resolve(c)).filter(m=>(filter==='all'||m.status===filter||m.side===filter)&&(!query||A.normalize('J'+m.id+' '+m.teams.map(id=>A.teamName(team(c,id))).join(' ')).includes(A.normalize(query))));$('#game-list').innerHTML=all.length?all.map(m=>card(c,m,admin)).join(''):'<div class="empty">Nenhuma partida encontrada neste filtro.</div>';}
function bracketPage(c){if(!comp.created){publicPage(null);return;}if(!c){$('#page-content').innerHTML=noCategory();return;}$('#page-content').innerHTML=hero('Chaveamento',c.name,'Acompanhe as duplas e gerencie cada partida.')+workflow(c,2)+`<div class="toolbar">${categorySelect(c)}<a class="btn primary" href="${url('index.html',c.id)}">Tabela para acompanhar</a><button data-action="print">Imprimir tabela completa</button></div>${c.confirmed?`${podium(c)}<div class="tabs"><button data-action="bracket-view" data-view="tree" class="${publicView!=='games-admin'?'active':''}">Chaveamento</button><button data-action="bracket-view" data-view="list" class="${publicView==='games-admin'?'active':''}">Lista de jogos</button>${isAdmin?`<button data-action="present-draw" data-cid="${esc(c.id)}">Apresentar sorteio</button><a class="btn" href="${url('inscricoes.html',c.id)}">Editar nomes das duplas</a>${redrawButton(c)}<button class="danger" data-action="reset-category" data-cid="${esc(c.id)}">Zerar categoria</button>`:''}</div><div id="bracket-body"></div>`:`<div class="empty"><h2>Cadastre as duplas para começar</h2>${isAdmin?`<a class="btn primary" href="${url('inscricoes.html',c.id)}">Cadastrar duplas</a>`:''}</div>`}`;if(c.confirmed)bracketBody(c);}
function bracketBody(c){if(publicView==='games-admin'){$('#bracket-body').innerHTML=conflictNotice(c)+filters()+'<div class="grid" id="game-list"></div>';listGames(c,isAdmin);return;}const r=A.resolve(c);$('#bracket-body').innerHTML=conflictNotice(c)+semifinalPanel(c)+(A.isFixed(c)?sequenceSummary(c,r):'<div class="notice">Categoria iniciada na versão anterior. O histórico e os cruzamentos existentes foram preservados. Novos sorteios seguem as tabelas fixas.</div>')+`<div class="legend"><span><i></i>Vencedores à esquerda</span><span><i class="l"></i>Perdedores à direita</span></div><section class="bracket-lane championship"><div class="lane-head"><div><h3>CHAVEAMENTO COMPLETO</h3><p class="help">Arraste com um dedo para mover. Use dois dedos para ampliar. No computador, arraste com o mouse ou use Ctrl + rolagem para dar zoom.</p></div><button data-action="bracket-fullscreen" class="primary small">Tela cheia</button></div><div class="bracket-tools"><button data-action="bracket-minus" aria-label="Diminuir zoom">−</button><output id="bracket-zoom-label">100%</output><button data-action="bracket-plus" aria-label="Aumentar zoom">+</button><button data-action="bracket-fit">Ver tudo</button><button data-action="bracket-readable">Ler nomes</button></div><div class="championship-scroll" tabindex="0" aria-label="Tabela completa, use os controles de zoom"><div class="bracket-surface"><div class="bracket-scale">${championship(c,r)}</div></div></div></section>`;requestAnimationFrame(()=>{measureBracket();drawConnections();setupBracketViewport();});}
let bracketZoom=0,bracketController=null,bracketPosition=null,bracketCategory=null;
function measureBracket(){for(const graph of document.querySelectorAll('.championship-tree')){const nodes=[...graph.querySelectorAll('.bracket-node')],pitch=Math.max(+graph.dataset.pitch,...nodes.map(n=>n.querySelector('.match').offsetHeight+24)),ratio=pitch/+graph.dataset.pitch;nodes.forEach(n=>n.style.top=(60+(+n.dataset.y-60)*ratio)+'px');graph.querySelectorAll('[data-label-y]').forEach(label=>label.style.top=(60+(+label.dataset.labelY-60)*ratio)+'px');graph.style.height=(+graph.dataset.height*ratio)+'px';}}
function setupBracketViewport(){const viewport=$('.championship-scroll'),graph=$('.championship-tree');if(!viewport||!graph)return;if(bracketController)bracketPosition={category:bracketCategory,view:bracketController.snapshot()};bracketController?.destroy();bracketCategory=getCat()?.id;bracketController=new BracketViewport.Controller(viewport,graph,$('.bracket-surface'),$('.bracket-scale'),value=>{bracketZoom=value;const label=$('#bracket-zoom-label');if(label)label.textContent=Math.round(value*100)+'%';});if(bracketPosition?.category===bracketCategory){bracketController.restore(bracketPosition.view);}else bracketController.fit();}
function setBracketZoom(value){bracketController?.setZoom(value);}
function fitBracket(){bracketController?.fit();}
function buildPrintTable(){const c=getCat();if(!c?.confirmed)return false;let sheet=$('#print-root');if(!sheet){sheet=document.createElement('section');sheet.id='print-root';document.body.append(sheet);}sheet.innerHTML=BracketPrint.create(comp,c);return true;}
function printTable(){if(!buildPrintTable()){notify('Confirme o sorteio da categoria antes de imprimir.');return;}window.print();}
window.addEventListener('beforeprint',buildPrintTable);
window.addEventListener('afterprint',()=>$('#print-root')?.remove());
async function openBracketFullscreen(){const panel=$('.championship');if(!panel||panel.classList.contains('bracket-fullscreen'))return;panel.classList.add('bracket-fullscreen');document.body.classList.add('bracket-open');const close=document.createElement('button');close.className='small bracket-close';close.dataset.action='bracket-close';close.textContent='Fechar tela cheia';panel.querySelector('.lane-head').append(close);panel.dataset.previousZoom=bracketZoom;try{if(panel.requestFullscreen)await panel.requestFullscreen();}catch{}try{await screen.orientation?.lock?.('landscape');}catch{}requestAnimationFrame(()=>{sizeFullscreen();fitBracket();});}
function sizeFullscreen(){const panel=$('.bracket-fullscreen');if(!panel)return;const viewport=panel.querySelector('.championship-scroll'),toolbar=panel.querySelector('.bracket-tools'),head=panel.querySelector('.lane-head');viewport.style.width='100%';viewport.style.height=Math.max(120,panel.clientHeight-head.offsetHeight-toolbar.offsetHeight)+'px';viewport.style.transform='none';viewport.style.marginLeft='0';}
function closeBracketFullscreen(){const panel=$('.bracket-fullscreen');if(!panel)return;if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});screen.orientation?.unlock?.();panel.classList.remove('bracket-fullscreen');document.body.classList.remove('bracket-open');panel.querySelector('.bracket-close')?.remove();const viewport=panel.querySelector('.championship-scroll');viewport.style.cssText='';setBracketZoom(+panel.dataset.previousZoom||.85);}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement)closeBracketFullscreen();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBracketFullscreen();});
function championship(c,r){
 const layout=BracketLayout.create(A.isFixed(c)?A.graph(c):A.models[c.count].games);
 const headings=layout.labels.map(label=>`<div class="bracket-half-heading ${label.side==='L'?'losers-heading':''}" data-label-y="${label.y}" style="left:${label.x}px;top:${label.y}px;width:${label.labelWidth}px">${label.text}<span>${label.side==='W'?'Avanço para a semifinal':'Avanço da repescagem para a semifinal'}</span></div>`).join('');
 const nodes=Object.values(layout.nodes).map(pos=>{
  const m=r[pos.id],caption=m.side==='S'?'Semifinal '+(pos.half?'B':'A'):m.side==='F'?'Final':'Disputa de 3º e 4º';
  return `<div class="bracket-node ${m.side==='F'?'title-node':''} ${m.side==='L'?'loser-node':''} ${['S','F','B'].includes(m.side)?'decision-node':''}" data-half="${pos.half===null?'decisions':pos.half?'B':'A'}" data-y="${pos.y}" style="left:${pos.x}px;top:${pos.y}px">${['S','F','B'].includes(m.side)?'<div class="decision-caption">'+caption+'</div>':''}${card(c,m,isAdmin,true)}</div>`;
 }).join('');
 return `<div class="championship-tree" data-pitch="${layout.pitch}" data-height="${layout.height}" data-center="${layout.centerX}" data-step="${layout.step}" style="width:${layout.width}px;height:${layout.height}px"><svg aria-hidden="true"></svg>${headings}${nodes}</div>`;
}
function tree(c,side,resolved){const depths={},groups={};for(const g of A.order(c)){const m=resolved[g.id];if(m.side!==side)continue;const ds=m.refs.filter(r=>r[0]==='V'&&resolved[+r.slice(1)]?.side===side).map(r=>depths[+r.slice(1)]||0);let depth=1+Math.max(0,...ds);if(side==='L'&&m.refs[0]==='R')continue;depths[m.id]=depth;(groups[depth]??=[]).push(m);}if(side==='L'){const waiting=Object.values(resolved).filter(m=>m.side==='L'&&m.refs[0]==='R');if(waiting.length)groups[1+Math.max(0,...Object.keys(groups).map(Number))]=waiting;}const max=Math.max(1,...Object.values(groups).map(g=>g.length)),height=Math.max(650,max*205+40);return `<div class="tree ${side==='L'?'reversed':''}" data-side="${side}" style="min-height:${height}px"><svg aria-hidden="true"></svg>${Object.entries(groups).map(([d,list])=>`<section class="round-col"><div class="round-label">${list.every(m=>m.refs[0]==='R')?'Próximos cruzamentos':side==='W'?'Rodada '+d:'Repescagem '+d}</div>${list.sort((a,b)=>a.id-b.id).map(m=>card(c,m,isAdmin,true)).join('')}</section>`).join('')}</div>`;}
function drawConnections(){const c=getCat();if(!c)return;const r=A.resolve(c);for(const treeEl of document.querySelectorAll('.tree,.championship-tree')){const rawBase=treeEl.getBoundingClientRect(),ratio=rawBase.width/treeEl.offsetWidth||1,rect=el=>{const p=el.getBoundingClientRect();return {left:p.left/ratio,right:p.right/ratio,top:p.top/ratio,height:p.height/ratio};},base=rect(treeEl),svg=treeEl.querySelector('svg');svg.setAttribute('width',treeEl.scrollWidth);svg.setAttribute('height',treeEl.scrollHeight);svg.innerHTML=[...treeEl.querySelectorAll('.match')].flatMap(b=>{const m=r[+b.dataset.game];return m.refs.map((ref,i)=>{if(!['V','P'].includes(ref[0]))return '';const source=r[+ref.slice(1)];if(ref[0]==='P'&&m.side!=='B')return '';const a=treeEl.querySelector(`[data-game="${+ref.slice(1)}"]`);if(!a)return '';const aa=rect(a),bb=rect(b),row=rect(b.querySelectorAll('.team-row')[i]),sameColumn=Math.abs(aa.left-bb.left)<5,rev=aa.left>bb.left,color=source.side==='L'||m.side==='L'?'#bbc95a':'#4cbbe9';let path,x2,y2;if(treeEl.classList.contains('championship-tree')&&['F','B'].includes(m.side)){const bronze=m.side==='B',center=+treeEl.dataset.center,step=+treeEl.dataset.step,x1=(bronze?aa.right:aa.left)-base.left,y1=aa.top-base.top+aa.height/2,gutter=bronze?center+2*step-28-i*10:center-28-i*10;x2=(bronze?bb.right:bb.left)-base.left;y2=row.top-base.top+row.height/2;path=`M${x1} ${y1} H${gutter} V${y2} H${x2}`;}else if(sameColumn){const gutter=aa.left-base.left-18-i*10,x1=aa.left-base.left,y1=aa.top-base.top+aa.height/2;x2=bb.left-base.left;y2=row.top-base.top+row.height/2;path=`M${x1} ${y1} H${gutter} V${y2} H${x2}`;}else{const x1=(rev?aa.left:aa.right)-base.left,y1=aa.top-base.top+aa.height/2;x2=(rev?bb.right:bb.left)-base.left;y2=row.top-base.top+row.height/2;const mid=x1+(x2-x1)*(i===0?.38:.68);path=`M${x1} ${y1} H${mid} V${y2} H${x2}`;}return `<path data-source="${source.id}" data-target="${m.id}" d="${path}" stroke="${color}" stroke-width="2" ${ref[0]==='P'?'stroke-dasharray="5 4"':''} fill="none"/><circle cx="${x2}" cy="${y2}" r="3" fill="${color}"/>`;});}).join('');}}
function openModal(title,body){const d=$('#modal');if(d.open)d.close();d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button type="button" class="small ghost" data-action="close-modal" aria-label="Fechar">✕</button></div>${body}`;d.showModal();}
function newCategory(){if(!comp.created){navigate('admin.html');return;}openModal('Nova categoria',`<form data-form="new-category"><label>Nome da categoria<input name="name" maxlength="80" required placeholder="Ex.: Misto iniciante" autofocus></label><label style="margin-top:15px">Quantidade de duplas<select name="count">${options(12)}</select></label><p class="error-text" id="modal-error" role="alert"></p><button class="primary" type="submit">Cadastrar duplas</button></form>`);}
function redrawButton(c,small=false){return `<button type="button" class="${small?'small ':''}danger" data-action="redraw-category" data-cid="${esc(c.id)}">Sortear novamente</button>`;}
function redrawModal(c){
 if(!c?.confirmed)return;
 const editing=page==='inscricoes.html'&&formDirty;
 openModal('Sortear novamente',`<form data-form="redraw-category" data-cid="${esc(c.id)}"><p>Um novo sorteio será realizado para <strong>${esc(c.name)}</strong>.</p><p><strong>O sorteio atual, os placares, as quadras atribuídas e a classificação desta categoria serão apagados.</strong> As duplas cadastradas e as outras categorias serão preservadas.</p>${editing?'<p class="notice">Há alterações de nomes não salvas. Cancele e salve antes de continuar. O novo sorteio usará os nomes já salvos.</p>':''}<p class="help">Você pode cancelar e exportar um backup antes de continuar.</p><label>Digite SORTEAR para confirmar<input name="confirmation" autocomplete="off" required placeholder="SORTEAR"></label><p class="error-text" id="modal-error" role="alert"></p><div class="actions"><button type="submit" class="danger">Confirmar novo sorteio</button><button type="button" data-action="close-modal">Cancelar</button></div></form>`);
}
function deleteCategoryModal(c){if(!c)return;openModal('Excluir categoria',`<form data-form="delete-category" data-cid="${esc(c.id)}"><p>Excluir <strong>${esc(c.name)}</strong> com todas as inscrições, sorteio e resultados? As outras categorias serão preservadas.</p><label>Digite EXCLUIR para confirmar<input name="confirmation" autocomplete="off" required placeholder="EXCLUIR"></label><p class="error-text" id="modal-error" role="alert"></p><div class="actions"><button type="submit" class="danger">Excluir categoria</button><button type="button" data-action="close-modal">Cancelar</button></div></form>`);}
function sequenceSummary(c,r){const blocks=A.blocks(c),current=blocks.findIndex(b=>b.ids.some(id=>!r[id].done));const entries=BracketLayout.create(A.models[c.count].games).entrySlots,bionic=entries.filter(entry=>entry.skipped>0).length;return `<section class="sequence-panel" aria-label="Sequência da tabela"><h3>Etapas da tabela</h3><p class="help">A sequência é uma referência. Qualquer partida com adversários definidos está liberada.</p><p class="entry-summary">${c.count} duplas${bionic?' · '+bionic+' biônico'+(bionic>1?'s':'')+' com entrada adiante na chave':''}</p><div class="sequence-blocks">${blocks.map((b,i)=>{const done=b.ids.every(id=>r[id].done),first=b.ids[0],last=b.ids[b.ids.length-1],label={W:'Vencedores',L:'Repescagem',S:'Semifinais',D:'Disputas de lugares'}[b.side];return `<div class="sequence-block ${done?'complete':i===current?'current':''}"><strong>${label}</strong><span>J${first}${last!==first?' a J'+last:''}</span><small>${done?'Concluído':b.ids.some(id=>r[id].status==='ready')?'Há partidas prontas':'Aguardando adversários'}</small></div>`;}).join('')}</div></section>`;}
function resetModal(c){const whole=!c;openModal(whole?'Zerar competição':'Zerar categoria',`<form data-form="reset" ${c?'data-cid="'+esc(c.id)+'"':''}><p>${whole?'Todos os nomes de categorias, inscrições, sorteios e resultados desta competição serão apagados. A configuração das quadras também voltará ao início.':'O sorteio, os resultados e as quadras atribuídas de <strong>'+esc(c.name)+'</strong> serão apagados. O nome da categoria e os atletas inscritos serão mantidos.'}</p><p class="help">${whole?'As outras categorias serão apagadas junto com esta competição.':'As outras categorias serão preservadas.'} Você pode exportar um backup antes.</p><label>Digite ZERAR para confirmar<input name="confirmation" autocomplete="off" required placeholder="ZERAR"></label><p class="error-text" id="modal-error" role="alert"></p><div class="actions"><button type="submit" class="danger">${whole?'Zerar toda a competição':'Zerar esta categoria'}</button><button type="button" data-action="close-modal">Cancelar</button></div></form>`);}
function editGame(cid,id,preferredCourt){const c=comp.categories.find(c=>c.id===cid),m=c&&A.resolve(c)[id];if(m?.conflict)return reviewGame(c,id);if(!m?.ready)return;const court=m.court||preferredCourt||1,wo=m.method==='wo';openModal((m.done?'Corrigir resultado':'Gerenciar jogo')+' · J'+id,`<form data-form="score" data-cid="${esc(cid)}" data-game="${id}"><p class="kicker">${esc(c.name)} · ${gameName(m)}</p><div class="matchup-title">${tname(c,m.teams[0])}<small>Contra</small>${tname(c,m.teams[1])}</div><label>Tipo de resultado<select name="method" id="result-method"><option value="score" ${!wo?'selected':''}>Placar</option><option value="wo" ${wo?'selected':''}>W.O.</option></select></label><div class="score-grid" id="score-fields" ${wo?'hidden':''}>${m.teams.map((t,i)=>`<label>${tname(c,t)}<input type="number" name="score${i}" ${wo?'disabled':''} min="0" max="999" step="1" inputmode="numeric" placeholder="0" value="${m.score?m.score[i]:''}" aria-label="Placar de ${tname(c,t)}"></label>`).join('')}</div><label id="wo-fields" style="margin:18px 0" ${wo?'':'hidden'}>Dupla vencedora por W.O.<select name="woWinner"><option value="">Selecione a dupla vencedora</option>${m.teams.map(t=>`<option value="${esc(t)}" ${wo&&m.winner===t?'selected':''}>${tname(c,t)}</option>`).join('')}</select></label><label>Quadra<select name="court">${Array.from({length:comp.courts},(_,i)=>`<option value="${i+1}" ${court===i+1?'selected':''}>Quadra ${i+1}</option>`).join('')}</select></label><p class="error-text" id="modal-error" role="alert"></p><div class="actions"><button type="submit" class="lime">${m.done?'Salvar correção':'Confirmar resultado'}</button>${m.status==='ready'?'<button type="button" data-action="start-game" class="primary">Iniciar partida</button><button type="button" data-action="queue-game">Definir quadra</button>':''}${m.done||m.status==='live'?'<button type="button" data-action="reopen-game" class="danger">Reabrir jogo</button>':''}</div></form>`);}
function chooseGame(court){const choices=comp.categories.flatMap(c=>Object.values(A.resolve(c)).filter(m=>m.status==='ready').map(m=>({c,m,error:A.availability(comp,c,m.id,court)})));openModal('Escolher jogo · Quadra '+court,`<form data-form="choose-game" data-court="${court}"><label>Partida<select name="match" required><option value="">Selecione uma partida pronta</option>${categoryMemory.ordered(comp.categories,getCat()?.id).map(c=>{const list=choices.filter(x=>x.c.id===c.id);return list.length?`<optgroup label="${esc(c.name)}">${list.map(({m,error})=>`<option value="${esc(JSON.stringify({cid:c.id,id:m.id}))}" ${error?'disabled':''}>J${m.id} · ${tname(c,m.teams[0])} Contra ${tname(c,m.teams[1])}${error?' · '+esc(error):''}</option>`).join('')}</optgroup>`:'';}).join('')}</select></label>${choices.length?'':'<p class="help" style="margin-top:15px">Nenhuma partida pronta. Aguarde os resultados anteriores ou cadastre uma categoria.</p>'}<p class="error-text" id="modal-error" role="alert"></p><button class="primary" type="submit" ${choices.some(x=>!x.error)?'':'disabled'}>Abrir jogo</button></form>`);}
async function applyGame(form,status){
 const c=comp.categories.find(c=>c.id===form.dataset.cid),id=+form.dataset.game,m=A.resolve(c)[id],fd=new FormData(form),court=Number(fd.get('court'));
 try{
  if(status==='queued'){A.assign(comp,c,id,court);$('#modal').close();if(await persist('Quadra definida.',false)){rememberCategory(c);render();}return;}
  const result={status,court,review:form.dataset.review==='true'};
  if(status==='done'){
   if(result.review&&fd.get('confirmParticipants')!=='yes')throw Error('Confirme os participantes corretos antes de registrar o resultado.');
   result.method=fd.get('method')==='wo'?'wo':'score';
   if(result.method==='wo'){result.woWinner=String(fd.get('woWinner')||'');if(!m.teams.includes(result.woWinner))throw Error('Selecione a dupla vencedora por W.O.');}
   else {if(fd.get('score0')===null||fd.get('score1')===null||String(fd.get('score0')).trim()===''||String(fd.get('score1')).trim()==='')throw Error('Preencha os dois placares.');result.score=[Number(fd.get('score0')),Number(fd.get('score1'))];}
  }
  const impact=A.previewChange(comp,c,id,result);
  if(impact.newConflicts.length&&!confirm('Esta correção muda os adversários de '+impact.newConflicts.map(n=>'J'+n).join(', ')+'. Os registros dessas partidas ficarão em revisão. '+impact.preserved+' resultado(s) válido(s) serão mantidos. Nenhum placar será transferido automaticamente para outra dupla. Confirmar correção?'))return;
  if(status==='ready'&&m.savedStatus==='done'&&!confirm('Reabrir somente J'+id+'? O registro desta partida será removido e os demais serão preservados para conferência.'))return;
  A.mutate(comp,c,id,result);$('#modal').close();
  if(await persist(status==='live'?'Partida iniciada.':status==='ready'?'Partida reaberta. Outros registros preservados.':impact.conflicts.length?'Correção salva. Confira as partidas em revisão.':'Resultado salvo. Demais resultados preservados.',false)){rememberCategory(c);render();}
 }catch(error){$('#modal-error').textContent=error.message;}
}
function exportBackup(){const blob=new Blob([JSON.stringify(comp,null,2)],{type:'application/json'}),link=document.createElement('a'),href=URL.createObjectURL(blob);link.href=href;link.download=(A.normalize(comp.name).replace(/[^a-z0-9]+/g,'-').slice(0,60)||'competicao')+'-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(href),1000);}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>3000000)throw Error('Backup muito grande. Limite de 3 MB.');const imported=A.validate(JSON.parse(await file.text()));if(!confirm('Substituir a competição atual por “'+imported.name+'”, com '+imported.categories.length+' categoria(s)?'))return;comp=imported;selected='';$('#modal').close();await persist('Competição importada.');}catch(e){notify(e.message||'Não foi possível importar o arquivo.');}};input.click();}
async function demo(){if(comp.categories.length&&!confirm('Substituir a competição atual por uma demonstração com dados fictícios?'))return;comp=A.fresh();comp.created=true;comp.name='Open Roteirizze · Demonstração';comp.courts=3;for(const [name,count] of [['Misto iniciante',12],['Masculino aberto',8]]){const c=A.category(name,count);c.teams.forEach((t,i)=>{t.a='Atleta '+String(i*2+1).padStart(2,'0');t.b='Atleta '+String(i*2+2).padStart(2,'0');});A.draw(c);c.confirmed=true;A.plan(c);comp.categories.push(c);}selected=comp.categories[0].id;await persist('Demonstração carregada. Escolha os jogos que deseja iniciar.');}
async function saveRegistration(form,action='save'){
 const c=comp.categories.find(c=>c.id===form.dataset.cid),fd=new FormData(form);
 try{
  const name=String(fd.get('categoryName')||'').trim();
  if(comp.categories.some(x=>x.id!==c.id&&A.normalize(x.name)===A.normalize(name)))throw Error('Já existe outra categoria com esse nome.');
  const count=c.confirmed?c.count:Number(fd.get('count')||c.count);
  const teams=Array.from({length:count},(_,i)=>({id:registrationDraft[i]?.id||c.teams[i]?.id||A.uid(),a:String(fd.get('a'+i)||''),b:String(fd.get('b'+i)||'')}));
  const candidate={...c};A.saveTeams(candidate,name,count,teams);
  if(action==='draw'&&!c.confirmed){A.draw(candidate);candidate.confirmed=true;A.plan(candidate);}
  Object.assign(c,candidate);
  if(!await persist(action==='draw'?'':c.confirmed?'Nomes atualizados. Sorteio e resultados preservados.':'Inscrições salvas. Você pode continuar depois.',action!=='draw'))return;
  if(action==='draw'){await presentDraw(comp.categories.find(x=>x.id===c.id));navigate('chaveamento.html',c.id,true);}
 }catch(e){const el=$('#registration-error');if(el)el.textContent=e.message;else notify(e.message);}
}
function resizeTeams(value){const form=$('[data-form="registration"]'),count=Number(value),c=getCat();if(!A.models[count]||c.confirmed)return;const fd=new FormData(form),old=Array.from({length:registrationDraft.length||c.count},(_,i)=>({id:registrationDraft[i]?.id||c.teams[i]?.id||A.uid(),a:String(fd.get('a'+i)||''),b:String(fd.get('b'+i)||'')}));registrationDraft=Array.from({length:count},(_,i)=>old[i]||{id:A.uid(),a:'',b:''});$('#team-inputs').innerHTML=teamInputs(registrationDraft,false);}
function fillTeams(sample=false){const form=$('[data-form="registration"]'),c=getCat(),count=Number(form.querySelector('[name="count"]').value);if(sample){for(let i=0;i<count;i++){form.elements['a'+i].value='Atleta '+String(i*2+1).padStart(2,'0');form.elements['b'+i].value='Atleta '+String(i*2+2).padStart(2,'0');}$('#bulk-error').textContent='';notify('Nomes fictícios preenchidos. Salve para continuar.');return;}try{const lines=$('#bulk-teams').value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(lines.length!==count)throw Error('Envie exatamente '+count+' linhas. Recebidas: '+lines.length+'.');const pairs=lines.map((s,i)=>{const parts=s.split(/\s*[\/;|]\s*/);if(parts.length!==2||parts.some(p=>!p.trim()||p.length>60))throw Error('Confira a dupla da linha '+(i+1)+'. Use Atleta 1 / Atleta 2.');return parts;});pairs.forEach(([a,b],i)=>{form.elements['a'+i].value=a;form.elements['b'+i].value=b;});$('#bulk-error').textContent='';notify('Duplas preenchidas. Confira os campos e salve.');}catch(e){$('#bulk-error').textContent=e.message;}}
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const fd=new FormData(form),kind=form.dataset.form;if(['login','password-reset','password-change'].includes(kind)){await handleAccessForm(form,kind,fd);return;}if(!access.authorized||access.saving||access.blocked)return;try{if(await handleManagementSubmit(form,fd,kind))return;if(kind==='create-competition'||kind==='competition'){const name=String(fd.get('name')).trim(),courts=Number(fd.get('courts'));if(!name)throw Error('Informe o nome da competição.');const used=Math.max(1,...comp.categories.flatMap(c=>Object.values(c.results).map(r=>r.court||1)));if(courts<used)throw Error('Há jogos registrados na quadra '+used+'. Mantenha essa quantidade ou zere os dados antes de reduzir.');comp.name=name;comp.courts=courts;comp.created=true;await persist(kind==='create-competition'?'Competição criada. Adicione uma categoria.':'Configuração salva.');}if(kind==='new-category'){const name=String(fd.get('name')).trim();if(!name)throw Error('Informe o nome da categoria.');if(comp.categories.some(c=>A.normalize(c.name)===A.normalize(name)))throw Error('Já existe uma categoria com esse nome.');const c=A.category(name,Number(fd.get('count')));comp.categories.push(c);selected=c.id;if(!await persist('',false))throw Error(storageError);$('#modal').close();navigate('inscricoes.html',c.id);}if(kind==='competition-logo'){await saveLogo();return;}if(kind==='registration')await saveRegistration(form,e.submitter?.value||'save');if(kind==='score')await applyGame(form,'done');if(kind==='choose-game'){const pick=JSON.parse(String(fd.get('match')));editGame(pick.cid,pick.id,+form.dataset.court);}if(kind==='redraw-category'){const c=comp.categories.find(c=>c.id===form.dataset.cid);if(!c)throw Error('Categoria não encontrada.');A.redrawCategory(c,fd.get('confirmation'));$('#modal').close();if(await persist('Novo sorteio salvo. Duplas preservadas.',false)){await presentDraw(comp.categories.find(x=>x.id===c.id));navigate('chaveamento.html',c.id,true);}return;}if(kind==='delete-category'){if(String(fd.get('confirmation')).trim()!=='EXCLUIR')throw Error('Digite EXCLUIR para confirmar.');A.deleteCategory(comp,form.dataset.cid);if(selected===form.dataset.cid)selected=comp.categories[0]?.id||'';$('#modal').close();if(await persist('Categoria excluída.')){const p=new URLSearchParams(location.search);if(selected)p.set('categoria',selected);else p.delete('categoria');history.replaceState(null,'',page+(p.size?'?'+p.toString():''));}}if(kind==='reset'){if(String(fd.get('confirmation')).trim()!=='ZERAR')throw Error('Digite ZERAR para confirmar.');const c=comp.categories.find(c=>c.id===form.dataset.cid);if(c)A.resetCategory(c);else{comp=A.fresh();selected='';}$('#modal').close();await persist(c?'Categoria zerada. Inscrições preservadas.':'Competição zerada.');}}catch(err){const el=$('#modal-error');if(el)el.textContent=err.message;else notify(err.message);}});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,c=comp.categories.find(c=>c.id===button.dataset.cid)||getCat();const adminActions=['remove-logo','cross-semifinals','apply-semifinal-cross','present-draw','new-competition','refresh-competitions','copy-public-link','toggle-organizer','show-conflicts','new-category','redraw-category','delete-category','reset-category','reset-competition','export','import','edit-game','choose-game','start-game','queue-game','reopen-game','apply-bulk','sample-names','demo','import-legacy'];if(adminActions.includes(action)&&(!isAdmin||!access.authorized||access.saving||(access.blocked&&action!=='export')))return;try{if(action==='refresh-portal'){await refreshPortal();return;}if(action==='cancel-logo-preview'){clearLogoDraft(true);refreshLogoPanel();return;}if(action==='open-navigation'){setNavigation(true);return;}if(action==='close-navigation'){setNavigation(false);return;}if(action==='remove-logo'){await saveLogo(null,true);return;}if(action==='cross-semifinals'){confirmCrossing(c);return;}if(action==='apply-semifinal-cross'){A.crossSemifinals(c);$('#modal').close();await persist('Cruzamento das semifinais salvo.');return;}if(action==='present-draw'){await presentDraw(c);return;}if(await handleManagementAction(action,button))return;if(action==='show-conflicts'){filter='conflict';publicView='games-admin';bracketBody(c);return;}if(action==='logout'){await cloud.logout();return;}if(action==='login-reset'){renderAccess('reset');return;}if(action==='login-back'){renderAccess('login');return;}if(action==='retry-connection'){await startApp();return;}if(action==='retry-save'){await persist('Alterações salvas.');return;}if(action==='reload-cloud'){if(confirm('Recarregar os dados salvos no servidor? As alterações não enviadas serão descartadas.')){clearLogoDraft();access.blocked=false;formDirty=false;await startApp();}return;}if(action==='import-legacy'){await importLegacy();return;}if(action==='new-category')newCategory();if(action==='close-modal')$('#modal').close();if(action==='redraw-category')redrawModal(c);if(action==='delete-category')deleteCategoryModal(c);if(action==='reset-category')resetModal(c);if(action==='reset-competition')resetModal(null);if(action==='export')exportBackup();if(action==='import')importBackup();if(action==='print')printTable();if(action==='bracket-fullscreen')openBracketFullscreen();if(action==='bracket-close')closeBracketFullscreen();if(action==='bracket-fit')fitBracket();if(action==='bracket-readable'&&bracketController){bracketController.readable();}if(action==='bracket-plus')setBracketZoom(bracketZoom+.15);if(action==='bracket-minus')setBracketZoom(bracketZoom-.15);if(action==='demo')await demo();if(action==='apply-bulk')fillTeams();if(action==='sample-names')fillTeams(true);if(action==='edit-game')editGame(c.id,+button.dataset.game,+button.dataset.court||null);if(action==='choose-game')chooseGame(+button.dataset.court);if(action==='start-game')await applyGame(button.closest('form'),'live');if(action==='queue-game')await applyGame(button.closest('form'),'queued');if(action==='reopen-game')await applyGame(button.closest('form'),'ready');if(action==='public-view'){publicView=button.dataset.view;render();}if(action==='bracket-view'){publicView=button.dataset.view==='list'?'games-admin':'tree';render();}if(action==='lane'){lane=button.dataset.lane;render();}}catch(err){notify(err.message);}});
document.addEventListener('change',e=>{if(e.target.closest('[data-form="competition-logo"]'))return;const el=e.target;if(el.closest('form[data-form]')&&access.authorized)formDirty=true;if(el.id==='competition-filter'){dashboardFilter=el.value;dashboardPage();}if(el.id==='category-select'){rememberCategory(comp.categories.find(c=>c.id===el.value));query='';filter='all';render();}if(el.id==='game-filter'){filter=el.value;listGames(getCat(),isAdmin);}if(el.id==='registration-count')resizeTeams(el.value);if(el.id==='result-method'){const wo=el.value==='wo';$('#score-fields').hidden=wo;$('#wo-fields').hidden=!wo;for(const input of $('#score-fields').querySelectorAll('input'))input.disabled=wo;for(const button of el.closest('form').querySelectorAll('[data-action="start-game"],[data-action="queue-game"]'))button.hidden=wo;}});
document.addEventListener('input',e=>{if(e.target.closest('[data-form="competition-logo"]'))return;if(e.target.closest('form[data-form]')&&access.authorized)formDirty=true;if(e.target.id==='game-search'){query=e.target.value;listGames(getCat(),isAdmin);}});
window.addEventListener('storage',e=>{if(e.key===cacheKey())pollCloud();});
